const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#1679A8','#F8D66D','#F47B62','#F5F1DF','#247B5A'],background:'#1679A8',seed:314159});
const P={water:'#1679A8',foam:'#c8f1e8',sand:'#F8D66D',road:'#F5F1DF',ink:'#17445a',coral:'#F47B62',leaf:'#247B5A',cream:'#fff9e8',curb:'#d7c8a6'};
const ev=(type,data)=>game.event(type,data);
const play={
 init(){
  this.orders=[
   {depot:[116,292],home:[238,292],name:'Lighthouse Café',color:'#F8D66D'},
   {depot:[378,292],home:[522,402],name:'Coral House',color:'#F47B62'},
   {depot:[654,292],home:[822,292],name:'Marina Market',color:'#247B5A'}
  ];
  this.blocks=[{x:282,y:246,w:42,h:84,k:'planter island'},{x:422,y:100,w:146,h:103,k:'building'},{x:678,y:350,w:140,h:74,k:'building'},{x:100,y:382,w:142,h:48,k:'hedge'},{x:848,y:105,w:27,h:120,k:'dock fence'}];
  this.rings=[];this.gulls=[80,286,492,700,886];
 },
 reset(){
  this.run=(this.run||0)+1;this.x=112;this.y=292;this.vx=0;this.vy=0;this.order=0;this.carry=false;
  this.timer=this.run===1?90:6;this.moved=0;this.bump=0;this.dust=0;this.driveSent=false;this.hitSent=false;this.freshSent=false;this.rings.length=0;this.warned=false;
  this.guide=this.run===1;this.nextStamp=0;
 },
 solid(x,y){
  if(x<42||x>918||y<82||y>494)return 'water edge';
  for(const b of this.blocks)if(x>b.x-13&&x<b.x+b.w+13&&y>b.y-13&&y<b.y+b.h+13)return b.k;
  return '';
 },
 bumpInto(k){
  if(this.bump>0)return;this.bump=.18;game.shake(3,.18);game.flash(P.coral,.11);GF.Sfx.noise({dur:.045,vol:.1,freq:580});
  if(game.time>1.2&&game.score>0&&!this.hitSent){this.hitSent=true;ev('obstacle_collision_blocked',{kind:k,blocked:true,score:game.score});}
 },
 pickup(){
  this.carry=true;const o=this.orders[this.order];
  game.burst(this.x,this.y,{count:12,speed:80,size:3,life:.42,colors:[P.cream,P.sand,o.color],gravity:90});GF.Sfx.beep({freq:500,to:740,dur:.12,type:'triangle',vol:.22});
 },
 deliver(){
  const o=this.orders[this.order],before=game.score,bonus=Math.max(0,Math.floor(this.timer)),points=100+bonus;
  game.addScore(points);ev('score_change',{before:before,after:game.score,delivery:o.name});
  this.carry=false;this.order++;this.timer=Math.min(99,this.timer+3);game.hitStop(.08);game.shake(4,.18);game.flash('#fff2c4',.35);
  game.burst(this.x,this.y,{count:30,speed:165,size:4,life:.8,colors:[o.color,P.sand,P.cream,P.coral],gravity:165});this.rings.push({x:this.x,y:this.y,r:13,life:.75,c:o.color});
  GF.Sfx.melody([[784,.07],[988,.08],[1175,.14]],{type:'triangle',vol:.22});
  if(this.order>=3){ev('delivery_sequence_completed',{delivered:3,destinations:['Lighthouse Café','Coral House','Marina Market'],score:game.score});game.win({message:'HARBOR ROUTE COMPLETE!'});}
 },
 update(dt){
  dt=Math.min(.05,dt);this.bump=Math.max(0,this.bump-dt);this.timer=Math.max(0,this.timer-dt);
  if(this.run>1&&!this.freshSent&&game.time>1.1){this.freshSent=true;ev('fresh_run_started',{run:this.run,fresh:true,timer:Math.ceil(this.timer)});}
  if(this.timer<=10&&!this.warned){this.warned=true;game.flash(P.coral,.2);GF.Sfx.beep({freq:660,dur:.07,type:'square',vol:.13});}
  if(this.timer<=0){game.gameOver({message:'SHIFT TIME RAN OUT — '+this.order+' / 3 DELIVERED'});return;}
  const o=this.orders[Math.min(2,this.order)],target=this.carry?o.home:o.depot;
  let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
  let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
  let il=Math.hypot(ix,iy);if(il){ix/=il;iy/=il;}
  let gx=0,gy=0;
  if(this.guide){let dx=target[0]-this.x,dy=target[1]-this.y,d=Math.hypot(dx,dy)||1;gx=dx/d;gy=dy/d;}
  let ax=gx*.82+ix*.55,ay=gy*.82+iy*.55,al=Math.hypot(ax,ay);
  if(!al){ax=0;ay=0;}else{ax/=al;ay/=al;}
  const speed=this.guide?245:210;this.vx=ax*speed;this.vy=ay*speed;
  const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;let h=this.solid(nx,this.y);
  if(h){this.vx=0;this.bumpInto(h);}else this.x=nx;
  h=this.solid(this.x,ny);if(h){this.vy=0;this.bumpInto(h);}else this.y=ny;
  this.moved+=Math.hypot(this.vx,this.vy)*dt;
  if(game.score>0&&this.moved>28&&!this.driveSent){this.driveSent=true;ev('courier_drive_confirmed',{distance:Math.round(this.moved),score:game.score,moving:true});}
  if(Math.hypot(this.x-target[0],this.y-target[1])<31){if(this.carry)this.deliver();else this.pickup();}
  if(this.dust<=0&&Math.hypot(this.vx,this.vy)>35){this.dust=.16;game.burst(this.x-7,this.y+8,{count:1,speed:12,size:2,life:.25,colors:['#d7c7a3'],gravity:0});}this.dust-=dt;
  for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.life-=dt;r.r+=90*dt;if(r.life<=0)this.rings.splice(i,1);}
 },
 marker(ctx,pt,o,parcel,dim){
  const pulse=1+Math.sin(game.time*5)*.08;ctx.save();ctx.globalAlpha=dim?.24:1;ctx.fillStyle=o.color;ctx.globalAlpha*=.2;ctx.beginPath();ctx.arc(pt[0],pt[1],38*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=dim?.45:1;ctx.strokeStyle=o.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(pt[0],pt[1],25,0,Math.PI*2);ctx.stroke();ctx.fillStyle=P.cream;ctx.beginPath();ctx.arc(pt[0],pt[1],16,0,Math.PI*2);ctx.fill();
  if(parcel){ctx.fillStyle=o.color;ctx.fillRect(pt[0]-8,pt[1]-6,16,12);ctx.strokeStyle=P.ink;ctx.lineWidth=1;ctx.strokeRect(pt[0]-8,pt[1]-6,16,12);}else GF.Draw.text(ctx,'⌂',pt[0],pt[1],{size:19,color:o.color,weight:'900'});GF.Draw.text(ctx,parcel?'PARCEL DEPOT':o.name,pt[0],pt[1]-44,{size:13,color:P.ink,weight:'900'});ctx.restore();
 },
 draw(ctx){
  const g=ctx.createLinearGradient(0,0,960,540);g.addColorStop(0,'#62cfca');g.addColorStop(1,P.water);ctx.fillStyle=g;ctx.fillRect(0,0,960,540);
  ctx.strokeStyle='rgba(245,241,223,.53)';ctx.lineWidth=2;for(let y=76;y<540;y+=31)for(let x=(y*3)%84;x<960;x+=88){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+21,y);ctx.stroke();}
  for(const x of this.gulls){ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,88+Math.sin(game.time+x)*5,5,3.5,5.7);ctx.arc(x+10,88+Math.sin(game.time+x)*5,5,3.5,5.7);ctx.stroke();}
  ctx.fillStyle=P.sand;ctx.fillRect(30,70,900,440);ctx.fillStyle=P.road;ctx.fillRect(48,246,864,92);ctx.fillRect(70,118,98,310);ctx.fillRect(334,106,74,355);ctx.fillRect(574,106,74,355);ctx.fillRect(790,106,76,355);
  ctx.strokeStyle=P.curb;ctx.lineWidth=3;ctx.setLineDash([12,13]);ctx.beginPath();ctx.moveTo(55,292);ctx.lineTo(905,292);ctx.stroke();ctx.setLineDash([]);
  for(const b of this.blocks){if(b.k==='building'){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(20,68,90,.18)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.x<600?P.coral:P.sand);ctx.fillStyle='rgba(255,249,232,.72)';for(let xx=b.x+18;xx<b.x+b.w-10;xx+=29)ctx.fillRect(xx,b.y+24,12,18);}else if(b.k==='dock fence'){ctx.strokeStyle='#8b6044';ctx.lineWidth=5;for(let yy=b.y;yy<b.y+b.h;yy+=17){ctx.beginPath();ctx.moveTo(b.x,yy);ctx.lineTo(b.x+b.w,yy);ctx.stroke();}}else{GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,10,'#d98b57');GF.Draw.roundRect(ctx,b.x+5,b.y+5,b.w-10,b.h-10,8,P.leaf);}}
  const active=this.orders[Math.min(this.order,2)],goal=this.carry?active.home:active.depot;ctx.save();ctx.strokeStyle=this.carry?active.color:P.leaf;ctx.globalAlpha=.55;ctx.lineWidth=3;ctx.setLineDash([8,9]);ctx.lineDashOffset=-game.time*35;ctx.beginPath();ctx.moveTo(this.x,this.y);ctx.lineTo(goal[0],goal[1]);ctx.stroke();ctx.restore();
  for(let i=this.order;i<3;i++){const o=this.orders[i];this.marker(ctx,i===this.order&&this.carry?o.home:o.depot,o,i!==this.order||!this.carry,i!==this.order);}
  for(const r of this.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.c;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
  ctx.save();ctx.translate(this.x,this.y);ctx.rotate(Math.atan2(this.vy,this.vx)||0);ctx.fillStyle='rgba(20,50,60,.2)';ctx.beginPath();ctx.ellipse(1,11,24,8,0,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-18,-10,36,20,9,P.coral);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(-15,-7,30,14);ctx.fillStyle=P.ink;ctx.beginPath();ctx.arc(-12,12,6,0,Math.PI*2);ctx.arc(12,12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=P.cream;ctx.fillRect(4,-6,13,8);if(this.carry){ctx.fillStyle=active.color;ctx.fillRect(-4,-24,16,13);ctx.strokeStyle=P.ink;ctx.lineWidth=2;ctx.strokeRect(-4,-24,16,13);}ctx.restore();
  GF.Draw.roundRect(ctx,16,14,170,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'TIME  '+Math.ceil(this.timer)+'s',29,38,{size:23,color:this.timer<=10?P.coral:P.cream,align:'left'});
  GF.Draw.roundRect(ctx,202,14,326,48,12,'rgba(255,249,232,.97)');GF.Draw.text(ctx,this.carry?'DELIVER: '+active.name:'PICK UP: Parcel Depot',218,38,{size:17,color:P.ink,align:'left'});
  GF.Draw.roundRect(ctx,610,14,150,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'DELIVERIES',685,29,{size:11,color:'#bde6df'});GF.Draw.text(ctx,this.order+' / 3',685,48,{size:20,color:P.cream});
  GF.Draw.roundRect(ctx,778,14,166,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'SCORE '+game.score,792,39,{size:20,color:P.sand,align:'left'});GF.Draw.text(ctx,'WASD / ARROWS • follow the route ribbon',480,520,{size:14,color:P.ink,weight:'900'});GF.Draw.vignette(ctx,960,540,.12);
 }
};
game.add('play',play);game.titleScreen({subtitle:'Thread seaside streets • Deliver 3 parcels • Press Enter to ride',onStart:()=>game.go('play')});
